local function cthun_attack(ctx,p)local value=6+(ctx:get_player_data(p,"cthun_attack_buff")or 0);for _,zone in ipairs({ctx:hand(p),ctx:deck(p),ctx:board(p),ctx:graveyard(p)})do for _,e in ipairs(zone)do if ctx:entity(e).card_id=="OG_280"then value=math.max(value,ctx:entity(e).attack)end end end;return value end
return {api_version=1,id="OG_096",name="Twilight Darkmender",text="<b>Battlecry:</b> If your C'Thun  has at least 10 Attack, restore #10 Health to your hero.",set="OG",type="minion",class="priest",rarity="rare",cost=5,attack=6,health=5,keywords={"battlecry"},on_battlecry=function(ctx,self)local p=ctx:controller(self);if cthun_attack(ctx,p)>=10 then ctx:heal(ctx:player(p).hero,10)end end}
